INSERT OR REPLACE INTO site_config ("id", "data") VALUES ('default', '{"name":"Kreatya Labs","legalName":"Kreatya Labs S.L.","claim":"Software que entiende tu negocio. IA que trabaja con tu equipo.","claimVariants":["Software que entiende tu negocio. IA que trabaja con tu equipo.","A medida. Desde el día uno.","Tu negocio, programado."],"description":"Desarrollo de software a medida e inteligencia artificial aplicada para pymes: ERP, CRM, apps y automatización con IA. Prueba nuestras demos y calcula tu ahorro.","url":"https://kreatya.es","domains":{"web":"kreatya.es","admin":"admin.kreatya.es","api":"api.kreatya.es","demo":"demo.kreatya.es"},"locale":"es-ES","contact":{"email":"hola@kreatya.es","phone":"+34 900 000 000","address":{"street":"Calle Ejemplo 1","city":"Madrid","postalCode":"28001","region":"Comunidad de Madrid","country":"ES"}},"social":{"linkedin":"https://www.linkedin.com/company/kreatya-labs","youtube":"https://www.youtube.com/@kreatyalabs","github":"https://github.com/kreatya-labs"},"calLink":"kreatya-labs/diagnostico","primaryCta":{"label":"Diagnóstico gratuito","href":"/diagnostico"}}');
INSERT OR REPLACE INTO sectors ("id", "slug", "name", "tagline", "pain", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sec_industria', 'industria', 'Industria', 'Del parte en papel al dato en planta, en tiempo real.', 'Órdenes de fabricación en Excel, partes de trabajo en papel y un ERP genérico que nadie en planta quiere usar.', '["Órdenes de fabricación","Partes de trabajo en tablet","Trazabilidad de lotes","Mantenimiento preventivo","Cuadro de mando OEE"]', '["ERP existente (SAP Business One, Sage, A3)","Lectores de código de barras","PLC vía OPC-UA","Power BI"]', '[{"type":"answer","text":"Un software a medida para industria conecta la oficina técnica con la planta: órdenes, partes, lotes y mantenimiento en una sola herramienta que se adapta a tu proceso. Un primer módulo útil suele estar en uso en 4–6 semanas y cuesta entre 15.000 y 40.000 €."},{"type":"h2","text":"Por qué el software estándar se queda corto en planta"},{"type":"p","text":"Cada taller tiene su forma de lanzar órdenes, de agrupar operaciones y de controlar la calidad. Los ERP generalistas obligan a adaptar el proceso al programa, y el resultado suele ser una doble contabilidad: lo que dice el sistema y lo que de verdad pasa en planta, apuntado en hojas de cálculo."},{"type":"p","text":"Nosotros empezamos al revés: recorremos la planta, dibujamos el plano del proceso real y construimos solo lo que aporta. Si ya tienes un ERP para la parte contable, lo integramos en lugar de sustituirlo."},{"type":"h2","text":"Qué solemos construir"},{"type":"list","ordered":false,"items":["Lanzamiento y seguimiento de órdenes de fabricación con prioridades visuales.","Partes de trabajo en tablet con fichaje por operación y foto de incidencias.","Trazabilidad de lotes de materia prima a producto terminado.","Mantenimiento preventivo con avisos y histórico por máquina.","Indicadores OEE calculados automáticamente."]},{"type":"h2","text":"Dónde aporta la IA"},{"type":"p","text":"La IA lee albaranes de proveedor y certificados de calidad para dar de alta lotes sin teclear, resume las incidencias del turno para el jefe de producción y detecta patrones en paradas de máquina."}]', '{"title":"Software para industria a medida | Kreatya Labs","description":"Software a medida para empresas industriales: órdenes de fabricación, partes en tablet, trazabilidad y OEE. Primer módulo en uso en 4–6 semanas."}', 'published', 0);
INSERT OR REPLACE INTO sectors ("id", "slug", "name", "tagline", "pain", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sec_logistica', 'logistica', 'Logística', 'Cada envío localizado, cada albarán digitalizado.', 'Rutas planificadas a mano, albaranes que se pierden y clientes que llaman para saber dónde está su pedido.', '["Planificación de rutas","App de conductor con firma digital","Portal de seguimiento para clientes","Gestión de almacén","Facturación automática por servicio"]', '["Transportistas (API de agencias)","Telemetría de flota","ERP contable","Google Maps Platform"]', '[{"type":"answer","text":"El software a medida para logística une planificación, conductores y clientes: rutas optimizadas, albarán digital con firma y un portal donde el cliente consulta su envío. Las empresas con las que trabajamos reducen entre un 50 y un 70 % el tiempo de facturación."},{"type":"h2","text":"El problema: información que llega tarde"},{"type":"p","text":"En logística el dato llega cuando el camión vuelve. Los albaranes firmados se escanean días después, la facturación se retrasa y el equipo de tráfico pasa horas al teléfono respondiendo a clientes."},{"type":"h2","text":"Qué solemos construir"},{"type":"list","ordered":false,"items":["Planificador de rutas con arrastrar y soltar y restricciones de horario.","App de conductor que funciona sin cobertura y sincroniza al recuperar señal.","Portal de clientes con seguimiento, documentos y incidencias.","Facturación generada automáticamente a partir de servicios cerrados."]},{"type":"h2","text":"Dónde aporta la IA"},{"type":"p","text":"Extracción automática de datos de albaranes y CMR, clasificación de incidencias y respuestas sugeridas a las consultas de clientes a partir del estado real del envío."}]', '{"title":"Software para logística y transporte | Kreatya Labs","description":"Software a medida para empresas de logística: rutas, app de conductor, albarán digital y portal de seguimiento. Factura hasta un 70 % más rápido."}', 'published', 1);
INSERT OR REPLACE INTO sectors ("id", "slug", "name", "tagline", "pain", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sec_retail', 'retail', 'Retail', 'Stock único entre tienda física y online.', 'Stock descuadrado entre tiendas y web, pedidos que se venden dos veces y promociones que se configuran en cinco sitios.', '["Stock unificado multialmacén","Gestión de pedidos omnicanal","Programa de fidelización","Reposición sugerida","Panel de ventas por tienda"]', '["Shopify, WooCommerce, PrestaShop","TPV","Marketplaces","Pasarelas de pago"]', '[{"type":"answer","text":"Un sistema a medida para retail mantiene un único stock para tiendas, web y marketplaces, centraliza pedidos y sugiere reposiciones. Lo integramos con tu TPV y tu tienda online actuales, sin cambiarlos, y el primer módulo suele estar en uso en 5–6 semanas."},{"type":"h2","text":"Omnicanal sin hojas de cálculo"},{"type":"p","text":"Cuando cada canal tiene su propio stock, el equipo pasa el día cuadrando inventarios. Un middleware a medida sincroniza existencias en tiempo real y reparte los pedidos al almacén o tienda más adecuado."},{"type":"h2","text":"Qué solemos construir"},{"type":"list","ordered":false,"items":["Sincronización de stock entre TPV, e-commerce y marketplaces.","Orquestador de pedidos con reglas de asignación.","Fidelización con monedero y cupones personalizados.","Reposición sugerida a partir de ventas y estacionalidad."]},{"type":"h2","text":"Dónde aporta la IA"},{"type":"p","text":"Previsión de demanda por tienda, descripciones de producto generadas y revisadas por tu equipo, y un asistente para atención al cliente que consulta el estado real del pedido."}]', '{"title":"Software para retail y comercio | Kreatya Labs","description":"Software a medida para retail: stock unificado entre tienda y online, pedidos omnicanal, fidelización y previsión de demanda con IA."}', 'published', 2);
INSERT OR REPLACE INTO sectors ("id", "slug", "name", "tagline", "pain", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sec_salud', 'salud', 'Salud', 'Menos papeleo, más tiempo con el paciente.', 'Citas por teléfono, consentimientos en papel y profesionales que dedican una hora al día a tareas administrativas.', '["Agenda y cita online","Consentimientos con firma digital","Historia clínica estructurada","Recordatorios automáticos","Facturación a mutuas"]', '["Software clínico existente","Mutuas y aseguradoras","Pasarela de pagos","WhatsApp Business"]', '[{"type":"answer","text":"Desarrollamos software a medida para clínicas y centros de salud: cita online, consentimientos digitales, recordatorios y facturación a mutuas, cumpliendo el RGPD para datos de salud. Las clínicas reducen un 40 % las ausencias con recordatorios automáticos."},{"type":"h2","text":"Datos de salud con las máximas garantías"},{"type":"p","text":"Los datos de salud son una categoría especial según el RGPD. Diseñamos con cifrado, registro de accesos y alojamiento en la UE desde el primer día, y te acompañamos en la evaluación de impacto."},{"type":"h2","text":"Qué solemos construir"},{"type":"list","ordered":false,"items":["Cita online conectada a la agenda real de cada profesional.","Consentimientos informados firmados en tablet.","Recordatorios por SMS o WhatsApp con confirmación.","Facturación agrupada a mutuas."]},{"type":"h2","text":"Dónde aporta la IA"},{"type":"p","text":"Transcripción y resumen de la consulta para que el profesional solo revise, clasificación de documentos entrantes y respuesta a preguntas frecuentes de pacientes."}]', '{"title":"Software para clínicas y salud | Kreatya Labs","description":"Software a medida para clínicas: cita online, consentimientos digitales, recordatorios y facturación a mutuas. RGPD para datos de salud."}', 'published', 3);
INSERT OR REPLACE INTO sectors ("id", "slug", "name", "tagline", "pain", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sec_agroalimentario', 'agroalimentario', 'Agroalimentario', 'Trazabilidad del campo al lineal.', 'Cuadernos de campo en papel, auditorías de calidad que paralizan la semana y trazabilidad imposible de reconstruir.', '["Cuaderno de campo digital","Trazabilidad de partidas","Control de calidad y APPCC","Liquidación a socios","Etiquetado"]', '["Básculas y etiquetadoras","SIEX","ERP contable","Sensores IoT"]', '[{"type":"answer","text":"El software a medida agroalimentario digitaliza el cuaderno de campo, la trazabilidad de partidas y el APPCC, y conecta básculas y etiquetadoras. Preparar una auditoría pasa de días a minutos porque toda la trazabilidad se reconstruye con un clic."},{"type":"h2","text":"La trazabilidad como ventaja comercial"},{"type":"p","text":"Las grandes cadenas exigen trazabilidad completa y rápida. Con un sistema a medida, cada partida sabe de qué parcela viene, qué tratamientos recibió y a qué cliente se envió."},{"type":"h2","text":"Qué solemos construir"},{"type":"list","ordered":false,"items":["Cuaderno de campo en móvil, también sin cobertura.","Trazabilidad lote a lote con códigos QR.","Registros APPCC con alertas.","Liquidaciones a socios de cooperativa."]},{"type":"h2","text":"Dónde aporta la IA"},{"type":"p","text":"Lectura automática de análisis de laboratorio, alertas de desviaciones en registros de calidad e informes de auditoría redactados a partir de los datos."}]', '{"title":"Software agroalimentario a medida | Kreatya Labs","description":"Software a medida para el sector agroalimentario: cuaderno de campo, trazabilidad, APPCC y liquidación a socios. Auditorías en minutos."}', 'published', 4);
INSERT OR REPLACE INTO sectors ("id", "slug", "name", "tagline", "pain", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sec_servicios', 'servicios', 'Servicios profesionales', 'Cada hora registrada, cada proyecto rentable.', 'Horas que no se imputan, presupuestos que se desvían sin que nadie lo vea y facturación que depende de una persona.', '["Imputación de horas","Control de rentabilidad por proyecto","Portal de cliente","Propuestas y presupuestos","Facturación recurrente"]', '["Google Workspace y Microsoft 365","Holded, A3, Sage","Calendarios","Firma electrónica"]', '[{"type":"answer","text":"Para despachos, consultoras y agencias desarrollamos herramientas a medida de imputación de horas, rentabilidad por proyecto y portal de cliente. Ver la desviación de cada proyecto en tiempo real suele recuperar entre un 8 y un 15 % de horas no facturadas."},{"type":"h2","text":"El margen se pierde en lo que no se mide"},{"type":"p","text":"En servicios profesionales el producto es el tiempo. Si las horas no se registran o se registran tarde, nadie sabe qué proyectos ganan dinero hasta que es demasiado tarde."},{"type":"h2","text":"Qué solemos construir"},{"type":"list","ordered":false,"items":["Imputación de horas desde el calendario en dos clics.","Rentabilidad por proyecto, cliente y persona.","Portal de cliente con documentos y aprobaciones.","Propuestas generadas a partir de plantillas y tarifas."]},{"type":"h2","text":"Dónde aporta la IA"},{"type":"p","text":"Propuestas redactadas a partir de las notas de la reunión, resúmenes de llamadas para el CRM y clasificación automática de documentos de clientes."}]', '{"title":"Software para despachos y consultoras | Kreatya Labs","description":"Software a medida para servicios profesionales: imputación de horas, rentabilidad por proyecto, portal de cliente y propuestas con IA."}', 'published', 5);
INSERT OR REPLACE INTO solutions ("id", "slug", "name", "kind", "tagline", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sol_software-a-medida', 'software-a-medida', 'Software a medida', 'portal', 'Hecho para tu negocio, no al revés.', '["Descubrimiento y plano del proceso","MVP en 4–6 semanas","Sprints de 2 semanas","Evolución continua"]', '["Cualquier sistema con API","Bases de datos existentes","Ficheros y FTP"]', '[{"type":"answer","text":"El software a medida es una aplicación diseñada para el proceso concreto de tu empresa, en lugar de adaptar tu empresa a un programa genérico. Con nosotros, un primer módulo útil está en uso en 4–6 semanas, y el código y los datos son tuyos."},{"type":"h2","text":"Cuándo tiene sentido"},{"type":"list","ordered":false,"items":["Tu proceso es una ventaja competitiva y el software estándar te obliga a cambiarlo.","Pagas licencias de varias herramientas que no se hablan entre sí.","Tu equipo mantiene hojas de cálculo paralelas al sistema oficial."]},{"type":"h2","text":"Cómo trabajamos"},{"type":"p","text":"Diagnóstico gratuito, plano del proceso con presupuesto cerrado por fase, construcción en sprints de dos semanas con entregas que se usan desde el primer sprint, y evolución con bolsa de horas."}]', '{"title":"Desarrollo de software a medida | Kreatya Labs","description":"Desarrollo de software a medida para pymes: MVP en uso en 4–6 semanas, presupuesto cerrado por fase y el código es tuyo."}', 'published', 0);
INSERT OR REPLACE INTO solutions ("id", "slug", "name", "kind", "tagline", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sol_erp-a-medida', 'erp-a-medida', 'ERP a medida', 'erp', 'Tu operativa entera, en un solo sistema que se adapta a ti.', '["Compras y ventas","Inventario y almacén","Producción","Facturación","Cuadros de mando"]', '["Contabilidad (A3, Sage, Holded)","Bancos","E-commerce","Verifactu"]', '[{"type":"answer","text":"Un ERP a medida cubre compras, ventas, inventario, producción y facturación siguiendo exactamente tu forma de trabajar, e integra tu contabilidad actual. Construimos primero el módulo que más duele y lo ponemos en uso en 4–6 semanas."},{"type":"h2","text":"ERP a medida frente a ERP estándar"},{"type":"p","text":"Un ERP estándar es más barato al principio, pero las adaptaciones, licencias por usuario y consultoría lo encarecen rápido. Uno a medida cuesta más al inicio y menos a medio plazo, y no tiene coste por usuario."},{"type":"h2","text":"Módulos habituales"},{"type":"list","ordered":false,"items":["Compras, proveedores y recepción de mercancía.","Ventas, presupuestos y pedidos.","Inventario multialmacén con trazabilidad.","Facturación compatible con Verifactu."]}]', '{"title":"ERP a medida para pymes | Kreatya Labs","description":"ERP a medida para pymes: compras, ventas, inventario, producción y facturación adaptados a tu proceso. Sin coste por usuario."}', 'published', 1);
INSERT OR REPLACE INTO solutions ("id", "slug", "name", "kind", "tagline", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sol_crm-a-medida', 'crm-a-medida', 'CRM a medida', 'crm', 'Un CRM que tu equipo comercial sí quiere usar.', '["Pipeline comercial","Ficha 360º de cliente","Propuestas","Automatizaciones","Previsión de ventas"]', '["Correo y calendario","Telefonía","ERP","Formularios web"]', '[{"type":"answer","text":"Un CRM a medida refleja tu ciclo de venta real, se conecta con tu ERP y tu correo y elimina los campos que nadie rellena. Con IA, resume llamadas y propone el siguiente paso de cada oportunidad."},{"type":"h2","text":"Por qué los CRM genéricos se abandonan"},{"type":"p","text":"Demasiados campos, etapas que no corresponden a tu venta y cero integración con el resto de sistemas. El comercial vuelve a su libreta."},{"type":"h2","text":"Qué incluye"},{"type":"list","ordered":false,"items":["Pipeline con tus etapas reales.","Ficha de cliente con pedidos, facturas e incidencias del ERP.","Propuestas generadas desde plantillas.","Resúmenes de llamadas con IA."]}]', '{"title":"CRM a medida | Kreatya Labs","description":"CRM a medida integrado con tu ERP y tu correo: pipeline real, ficha 360º, propuestas y resúmenes de llamadas con IA."}', 'published', 2);
INSERT OR REPLACE INTO solutions ("id", "slug", "name", "kind", "tagline", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sol_apps-moviles', 'apps-moviles', 'Apps móviles a medida', 'app', 'Apps para tu equipo de campo y tus clientes.', '["App de técnicos y conductores","App de clientes","Modo sin conexión","Firma y fotos","Notificaciones"]', '["Tu ERP o CRM","Mapas","Pagos","Sensores y escáneres"]', '[{"type":"answer","text":"Desarrollamos aplicaciones a medida para iOS y Android con una sola base de código: apps para equipos de campo que funcionan sin cobertura y apps para clientes conectadas a tus sistemas. Una primera versión publicada suele estar lista en 6–8 semanas."},{"type":"h2","text":"Apps de campo"},{"type":"p","text":"Partes de trabajo, inspecciones, entregas con firma y fotos. Funcionan sin conexión y sincronizan al recuperar cobertura."},{"type":"h2","text":"Apps de cliente"},{"type":"p","text":"Pedidos, seguimiento, citas, fidelización. Siempre conectadas a tus datos reales, sin duplicar información."}]', '{"title":"Desarrollo de apps a medida | Kreatya Labs","description":"Apps móviles a medida para iOS y Android: apps de campo sin conexión y apps de cliente integradas con tu ERP o CRM."}', 'published', 3);
INSERT OR REPLACE INTO solutions ("id", "slug", "name", "kind", "tagline", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sol_portales-clientes', 'portales-clientes', 'Portales de cliente y proveedor', 'portal', 'Que tus clientes se sirvan solos.', '["Área privada","Pedidos y documentos","Incidencias","Aprobaciones","Pagos"]', '["ERP","Firma electrónica","Pasarelas de pago","SSO"]', '[{"type":"answer","text":"Un portal de cliente a medida permite consultar pedidos, descargar documentos, abrir incidencias y aprobar presupuestos sin llamar ni enviar correos. Reduce las consultas repetitivas al equipo y mejora la experiencia del cliente."},{"type":"h2","text":"Qué resuelve"},{"type":"list","ordered":false,"items":["Llamadas para preguntar por el estado de un pedido.","Correos para pedir duplicados de facturas.","Aprobaciones que se pierden en la bandeja de entrada."]}]', '{"title":"Portal de clientes a medida | Kreatya Labs","description":"Portales de cliente y proveedor a medida: pedidos, documentos, incidencias y aprobaciones conectados a tu ERP."}', 'published', 4);
INSERT OR REPLACE INTO solutions ("id", "slug", "name", "kind", "tagline", "modules", "integrations", "blocks", "seo", "status", "order") VALUES ('sol_integraciones', 'integraciones', 'Integraciones entre sistemas', 'integracion', 'Que tus programas por fin se hablen.', '["Conectores a medida","Sincronización de datos","Monitorización","Alertas de errores"]', '["ERP, CRM, e-commerce","APIs de terceros","Ficheros EDI y FTP","Bases de datos"]', '[{"type":"answer","text":"Conectamos los programas que ya usas (ERP, CRM, tienda online, contabilidad) para que los datos fluyan solos y nadie tenga que copiarlos a mano. Cada integración incluye monitorización y alertas si algo falla."},{"type":"h2","text":"Señales de que necesitas integrar"},{"type":"list","ordered":false,"items":["Alguien copia pedidos de la web al ERP.","El stock no coincide entre sistemas.","Los informes se montan exportando a Excel desde tres sitios."]}]', '{"title":"Integración de sistemas y APIs | Kreatya Labs","description":"Integramos ERP, CRM, e-commerce y contabilidad para que los datos fluyan solos. Monitorización y alertas incluidas."}', 'published', 5);
