INSERT OR REPLACE INTO testimonials ("id", "name", "role", "company", "quote", "rating", "video", "consent") VALUES ('t-transportes', 'Marta Gil', 'Directora de operaciones', 'Transportes Levante', 'En seis semanas los conductores ya firmaban albaranes en la app. Facturamos el mismo día del servicio, no a final de mes.', 5, NULL, 1);
INSERT OR REPLACE INTO testimonials ("id", "name", "role", "company", "quote", "rating", "video", "consent") VALUES ('t-metal', 'Jordi Puig', 'Gerente', 'Cliente del sector industrial', 'Por fin el sistema dice lo mismo que la planta. Hemos dejado de imprimir órdenes de trabajo.', 5, NULL, 1);
INSERT OR REPLACE INTO testimonials ("id", "name", "role", "company", "quote", "rating", "video", "consent") VALUES ('t-clinica', 'Dra. Lucía Moreno', 'Directora médica', 'Clínica Dental Sonrisa', 'Los recordatorios automáticos han reducido las ausencias casi a la mitad. Y el equipo de recepción respira.', 5, NULL, 1);
INSERT OR REPLACE INTO testimonials ("id", "name", "role", "company", "quote", "rating", "video", "consent") VALUES ('t-coop', 'Antonio Ruiz', 'Responsable de calidad', 'Cooperativa del Valle', 'La última auditoría la preparamos en una mañana. Antes era una semana entera.', 5, NULL, 1);
INSERT OR REPLACE INTO projects ("id", "slug", "title", "client_name", "confidential", "company_size", "duration_weeks", "summary", "challenge", "solution", "ai_role", "process_before", "process_after", "metrics", "main_video", "card_video", "cover", "gallery", "demo_type", "demo_url", "demo_tour", "testimonial_id", "featured", "seo", "status", "publish_at", "created_at", "updated_at") VALUES ('prj_albaran-digital-transportes-levante', 'albaran-digital-transportes-levante', 'Albarán digital y facturación el mismo día', 'Transportes Levante', 0, 'mediana', 6, 'App de conductor con firma digital y facturación automática para una flota de 60 camiones.', 'Los albaranes firmados volvían en la cabina del camión y se escaneaban días después. La facturación se cerraba a final de mes, con errores y retrasos de cobro.', 'App de conductor que funciona sin cobertura, con firma y fotos de entrega; panel de tráfico con estado en tiempo real; facturación generada automáticamente al cerrar cada servicio.', 'La IA lee los CMR y albaranes de terceros fotografiados por el conductor y rellena los datos del servicio sin teclear.', '[{"label":"Entrega"},{"label":"Albarán en papel"},{"label":"Vuelta a base"},{"label":"Escaneo manual"},{"label":"Factura a fin de mes"}]', '[{"label":"Entrega"},{"label":"Firma en la app"},{"label":"Factura automática"}]', '[{"value":70,"unit":"%","description":"menos tiempo de facturación","prefix":"−"},{"value":12,"unit":"h/sem","description":"ahorradas en administración"},{"value":18,"unit":"días","description":"menos de periodo medio de cobro","prefix":"−"},{"value":6,"unit":"semanas","description":"hasta la primera versión en uso"}]', '{"provider":"youtube","ref":"pendiente","poster":"/media/proyectos/albaran-digital-transportes-levante/cover.svg","durationSeconds":94,"transcript":"Recorrido por la app de conductor: lista de servicios del día, navegación, entrega con firma y foto, y cómo el panel de tráfico recibe el albarán al instante y genera la factura."}', NULL, '/media/proyectos/albaran-digital-transportes-levante/cover.svg', '[{"src":"/media/proyectos/albaran-digital-transportes-levante/panel.svg","alt":"Panel de tráfico con los servicios del día y su estado en el mapa","device":"desktop","width":1440,"height":900},{"src":"/media/proyectos/albaran-digital-transportes-levante/app.svg","alt":"App de conductor mostrando la pantalla de firma del albarán","device":"mobile","width":390,"height":844},{"src":"/media/proyectos/albaran-digital-transportes-levante/facturas.svg","alt":"Listado de facturas generadas automáticamente al cerrar servicios","device":"desktop","width":1440,"height":900}]', 'tour', NULL, '[{"image":"/media/proyectos/albaran-digital-transportes-levante/panel.svg","title":"Panel de tráfico","text":"Tráfico ve todos los servicios del día y su estado en tiempo real.","hotspot":{"x":30,"y":35}},{"image":"/media/proyectos/albaran-digital-transportes-levante/app.svg","title":"Firma en destino","text":"El conductor recoge la firma y una foto. Funciona sin cobertura.","hotspot":{"x":50,"y":70}},{"image":"/media/proyectos/albaran-digital-transportes-levante/facturas.svg","title":"Factura automática","text":"Al cerrar el servicio se genera la factura. Sin teclear.","hotspot":{"x":70,"y":30}}]', 't-transportes', 1, '{"title":"Caso: albarán digital en logística | Kreatya Labs","description":"App de conductor con firma digital y facturación automática: −70 % de tiempo de facturación en una flota de 60 camiones."}', 'published', '2026-06-10T09:00:00.000Z', '2026-06-10T09:00:00.000Z', '2026-09-01T09:00:00.000Z');
