INSERT OR REPLACE INTO projects ("id", "slug", "title", "client_name", "confidential", "company_size", "duration_weeks", "summary", "challenge", "solution", "ai_role", "process_before", "process_after", "metrics", "main_video", "card_video", "cover", "gallery", "demo_type", "demo_url", "demo_tour", "testimonial_id", "featured", "seo", "status", "publish_at", "created_at", "updated_at") VALUES ('prj_portal-clientes-asesoria', 'portal-clientes-asesoria', 'Portal de clientes para una asesoría', 'Asesoría Martín & Asociados', 0, 'pequena', 5, 'Portal donde 400 clientes suben facturas y la IA las clasifica para contabilidad.', 'Los clientes enviaban facturas por correo, WhatsApp y en mano. Clasificarlas consumía la primera semana de cada trimestre.', 'Portal de cliente con subida de documentos, avisos de plazos fiscales y bandeja de revisión para el equipo.', 'La IA extrae emisor, fecha, base e IVA de cada factura y la clasifica; el equipo solo revisa las dudosas.', '[{"label":"Correo / WhatsApp"},{"label":"Descarga"},{"label":"Tecleo manual"},{"label":"Contabilidad"}]', '[{"label":"Portal"},{"label":"Extracción con IA"},{"label":"Revisión"},{"label":"Contabilidad"}]', '[{"value":80,"unit":"%","description":"de facturas sin teclear"},{"value":25,"unit":"h/sem","description":"ahorradas en cierre trimestral"},{"value":400,"unit":"clientes","description":"usando el portal"}]', NULL, NULL, '/media/proyectos/portal-clientes-asesoria/cover.svg', '[{"src":"/media/proyectos/portal-clientes-asesoria/portal.svg","alt":"Portal de cliente con documentos pendientes y plazos fiscales","device":"desktop","width":1440,"height":900},{"src":"/media/proyectos/portal-clientes-asesoria/revision.svg","alt":"Bandeja de revisión con datos extraídos de una factura por la IA","device":"desktop","width":1440,"height":900}]', 'tour', NULL, '[{"image":"/media/proyectos/portal-clientes-asesoria/portal.svg","title":"Subida en un clic","text":"El cliente arrastra sus facturas o las fotografía con el móvil.","hotspot":{"x":35,"y":50}},{"image":"/media/proyectos/portal-clientes-asesoria/revision.svg","title":"La IA hace el trabajo pesado","text":"Emisor, fecha, base e IVA extraídos. Solo revisas lo dudoso.","hotspot":{"x":65,"y":40}}]', NULL, 1, '{"title":"Caso: portal de clientes con IA | Kreatya Labs","description":"Portal de clientes para una asesoría: la IA clasifica el 80 % de las facturas y ahorra 25 horas semanales en el cierre."}', 'published', '2026-07-22T09:00:00.000Z', '2026-07-22T09:00:00.000Z', '2026-09-15T09:00:00.000Z');
