INSERT OR REPLACE INTO authors ("id", "slug", "name", "role", "bio", "credentials", "links") VALUES ('aut_equipo-kreatya', 'equipo-kreatya', 'Equipo Kreatya Labs', 'Arquitectura de software e IA', 'Equipo de ingenieros y consultores de procesos especializados en software a medida e IA aplicada para pymes.', '["Más de 40 proyectos entregados","Ingeniería informática"]', '["https://www.linkedin.com/company/kreatya-labs"]');
INSERT OR REPLACE INTO posts ("id", "kind", "slug", "title", "excerpt", "blocks", "author_id", "pillar", "solution_id", "sector_id", "project_id", "seo", "status", "publish_at") VALUES ('pst_cuanto-cuesta-un-software-a-medida', 'guia', 'cuanto-cuesta-un-software-a-medida', '¿Cuánto cuesta un software a medida en 2026?', 'Rangos reales de precio, qué los encarece y cómo pedir un presupuesto comparable.', '[{"type":"answer","text":"Un software a medida para una pyme cuesta entre 12.000 € (un MVP con un módulo) y 80.000 € (un sistema completo con varias integraciones). El precio depende sobre todo del número de módulos, de las integraciones y de la complejidad de los permisos y flujos."},{"type":"h2","text":"Qué determina el precio"},{"type":"list","ordered":false,"items":["Número de módulos o pantallas principales.","Integraciones con otros sistemas.","Apps móviles y modo sin conexión.","Uso de IA y volumen de documentos.","Requisitos de seguridad y normativa."]},{"type":"h2","text":"Cómo comparar presupuestos"},{"type":"p","text":"Pide presupuestos cerrados por fase, con entregables concretos y propiedad del código. Desconfía de precios por hora sin límite y de presupuestos que no detallan qué incluye cada fase."}]', 'aut_equipo-kreatya', 'software-a-medida', 'sol_software-a-medida', NULL, 'prj_erp-fabricacion-metal', '{"title":"¿Cuánto cuesta un software a medida? (2026)","description":"Rangos de precio reales de un software a medida para pymes, qué factores lo encarecen y cómo comparar presupuestos."}', 'published', '2026-09-01T09:00:00.000Z');
INSERT OR REPLACE INTO posts ("id", "kind", "slug", "title", "excerpt", "blocks", "author_id", "pillar", "solution_id", "sector_id", "project_id", "seo", "status", "publish_at") VALUES ('pst_como-implantar-ia-en-una-pyme', 'blog', 'como-implantar-ia-en-una-pyme', 'Cómo implantar IA en una pyme sin perder el control', 'Una guía práctica en cinco pasos para empezar por lo que ahorra horas de verdad.', '[{"type":"answer","text":"Para implantar IA en una pyme, empieza por una tarea repetitiva y medible (leer facturas, resumir llamadas), mide las horas que consume hoy, prueba con datos reales durante dos semanas y despliega solo si el ahorro es claro. La IA debe proponer y tu equipo, decidir."},{"type":"h2","text":"1. Elige una tarea, no una tecnología"},{"type":"p","text":"El error más común es empezar por la herramienta. Empieza por la tarea que más horas consume y que sigue reglas claras."},{"type":"h2","text":"2. Mide antes de empezar"},{"type":"p","text":"Sin una línea base no podrás demostrar el ahorro. Cuenta horas por semana y errores por mes."},{"type":"h2","text":"3. Cuida la privacidad"},{"type":"p","text":"Elige proveedores con procesamiento en la UE, firma acuerdos de encargo y revisa qué obligaciones te aplican del Reglamento europeo de IA."}]', 'aut_equipo-kreatya', 'ia-para-empresas', NULL, NULL, 'prj_portal-clientes-asesoria', '{"title":"Cómo implantar IA en una pyme paso a paso","description":"Guía práctica para implantar inteligencia artificial en una pyme: casos de uso, privacidad, Reglamento de IA y medición del ahorro."}', 'published', '2026-09-20T09:00:00.000Z');
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_0', '¿Cuánto cuesta un software a medida?', 'Un MVP útil parte de unos 12.000 € y un sistema completo suele estar entre 25.000 y 80.000 €, según módulos e integraciones. Publicamos rangos orientativos y cerramos presupuesto por fase, sin sorpresas.', 'home', NULL, 0);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_1', '¿En cuánto tiempo tendré algo funcionando?', 'El primer módulo útil está en uso en 4–6 semanas. Trabajamos en sprints de dos semanas y en cada uno entregamos algo que tu equipo puede usar.', 'home', NULL, 1);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_2', '¿De quién es el código?', 'Tuyo. El código fuente, los datos y la documentación son propiedad del cliente desde el primer día.', 'home', NULL, 2);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_3', '¿Podéis integraros con el software que ya usamos?', 'Sí. Trabajamos con ERP, CRM, contabilidad y e-commerce habituales en España. Si tiene API o base de datos accesible, lo conectamos.', 'home', NULL, 3);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_4', '¿Cómo usáis la IA con nuestros datos?', 'Solo donde ahorra tiempo medible, con proveedores que procesan los datos en la UE y sin entrenar modelos con tu información. Cumplimos RGPD y el Reglamento europeo de IA.', 'home', NULL, 4);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_5', '¿El diagnóstico es realmente gratuito?', 'Sí. Es una sesión de 45 minutos en la que analizamos tu proceso y te damos una estimación orientativa, sin compromiso.', 'pricing', NULL, 5);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_6', '¿Qué incluye la evolución mensual?', 'Una bolsa de horas para mejoras, soporte y mantenimiento. Las horas no consumidas se acumulan al mes siguiente.', 'pricing', NULL, 6);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_7', '¿Hay coste por usuario?', 'No. El software es tuyo y no pagas licencias por usuario. Solo el alojamiento, que suele ser muy bajo.', 'pricing', NULL, 7);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_8', '¿La IA sustituye a mi equipo?', 'No. La IA se encarga de tareas repetitivas (leer documentos, resumir, clasificar) y tu equipo revisa y decide. Es un compañero, no un sustituto.', 'ai', NULL, 8);
INSERT OR REPLACE INTO faqs ("id", "question", "answer", "scope", "scope_id", "order") VALUES ('faq_9', '¿Dónde se procesan los datos?', 'En infraestructura europea siempre que es posible. Te informamos de cada proveedor y firmamos los acuerdos de encargo de tratamiento necesarios.', 'ai', NULL, 9);
INSERT OR REPLACE INTO pricing_tiers ("id", "slug", "name", "price_from", "price_to", "unit", "description", "includes", "order") VALUES ('prc_mvp', 'mvp', 'MVP', 12000, 25000, 'EUR', 'Un primer módulo en uso en 4–6 semanas para validar con tu equipo.', '["Diagnóstico y plano del proceso","1–2 módulos principales","1 integración","Formación y puesta en marcha"]', 0);
INSERT OR REPLACE INTO pricing_tiers ("id", "slug", "name", "price_from", "price_to", "unit", "description", "includes", "order") VALUES ('prc_sistema-completo', 'sistema-completo', 'Sistema completo', 25000, 80000, 'EUR', 'ERP, CRM o plataforma completa por fases, con presupuesto cerrado por fase.', '["Todo lo del MVP","Varios módulos e integraciones","Apps móviles si se necesitan","IA aplicada a tareas clave"]', 1);
INSERT OR REPLACE INTO pricing_tiers ("id", "slug", "name", "price_from", "price_to", "unit", "description", "includes", "order") VALUES ('prc_evolucion', 'evolucion', 'Evolución mensual', 900, NULL, 'EUR/mes', 'Bolsa de horas para mejoras, soporte y mantenimiento.', '["Horas acumulables","Soporte prioritario","Actualizaciones de seguridad","Informe mensual"]', 2);
